with temp as (select product_id from products group by product_id),temp1 as (select product_id , max(change_date) as lastdate from products where change_date<='2019-08-16' group by product_id),temp2 as (select t.product_id , t1.lastdate from temp as t left join temp1 as t1 on t.product_id=t1.product_id)
select t.product_id , coalesce(p.new_price,10) as price from temp2 as t left join products as p on p.product_id=t.product_id and t.lastdate=p.change_date